function divideLater(a, b, callback) {
  setTimeout(() => {
    if (b === 0) {
      callback(new Error("divide by zero"));
    }
    callback(null, a / b);
  }, 0);
}

divideLater(6, 0, (error, result) => {
  if (error) {
    console.log("error: " + error.message);
    return;
  }
  console.log("result: " + result);
});
